"""Numbers quoted in main.tex (Paper E) and how to recompute them.

Every entry of build() is  Check(id, where, paper, getter, kind, tol, reason, src, full, old, quantity):
  paper   the value as printed in main.tex (a string keeps the number of quoted digits; kind 'digits' accepts a deviation of half a unit
          of the last quoted digit, `tol` multiplies that half unit),
  getter  function(ctx) -> computed value, reading the files written by the jobs of ../verify.py (or the shipped files when a job is skipped),
  kind    digits | rel | abs | le | ge | range | bool | eq,   reason = why a tolerance other than `digits` is used,
  old     the wording of main.tex when it differs from the value tested here (proposed correction: the check tests the corrected value).
Checks with full=True are evaluated on the data regenerated by `verify.sh --full` (verification/regen/code).
`where` is the section of main.tex.
"""
import json, re, math, os


def build(Check):
    CH = []

    def add(id, where, quantity, paper, get, kind='digits', tol=None, reason='', src=(), full=False, old=None):
        CH.append(Check(id, where, paper, get, kind, tol, reason, src, full, old, quantity))

    FULLKEYS = ('thr.', 'dom.', 'fam.', 'sup.', 'kscan.', 'near.', 'univ.', 'sign.n_', 'sign.min_', 'sign.mono_', 'sign.ustar_min', 'sign.ustar_max', 'sign.ustar_A', 'sign.ustar_A0.02_B', 'sign.nchanges', 'sign.ustar_smallest')

    def an(id, where, quantity, paper, key, kind='digits', tol=None, reason='', old=None, scale=1.0, src=()):
        g = (lambda c, key=key, scale=scale: c.A(key) * scale)
        add(id, where, quantity, paper, g, kind, tol, reason, src or ('nl_analyze_stored',), False, old)
        if key.startswith(FULLKEYS):
            add(id + '@full', where, quantity + ' [regenerated]', paper, g, kind, tol, reason, ('full_nl_analyze_stored',), True, old)

    # ================================================================================================ symbolic (sympy), Secs. 2-6
    S = [('A1', 'Sec. 3', '(dM/dr)_m = 3Ma/[r(r^3+a)]'), ('A2', 'Eq. Gfamily', 'G = 6 l0^2 M^2 (m/m0)^s / r^4'),
         ('A3', 'Sec. 4 II', 'Moebius closure: dM/dm = r^6/(r^3+2l^2m)^2 > 0'), ('A4', 'Sec. 4 II', 'inverse m = M r^3/(r^3 - 2 l^2 M)'),
         ('A5', 'Sec. 4 II', 'm -> infinity at M = r^3/2l^2, pole at m = -r^3/2l^2'), ('A6', 'Sec. 4 II', 'G = 6 l^2 M^2/r^4 (n = 2)'),
         ('A7', 'Sec. 4 I', 's = -1: G = (3M/r) a/(r^3+a)'), ('A8', 'Sec. 4 I', '-1<s<0, large M: G -> 3M/r independent of s'),
         ('A9', 'Sec. 4 III', 'dM/dm = r^3 (r^3 - s a)/(r^3+a)^2: fold at a = r^3/s'),
         ('A10', 'Sec. 4 III', 'fold value for s = 1: M_max = sqrt(m0 R^3/8 l0^2)'), ('A11', 'Sec. 4 III', 'fold value for s = 2: (2/3)(m0^2 R^3/4 l0^2)^(1/3)'),
         ('A12', 'Sec. 3 Validation', 'linear drive M_m/(R|dr_-/dm|) = kappa_- for any closure'), ('A13', 'Eq. dtr', 'DTR relation: dM_+/f_+ = dM_-/f_-'),
         ('A14', 'Sec. 2', 'M* = 3 sqrt3 l/4: double horizon at r = 4M*/3'), ('A15', 'Sec. 2', 'kappa_+- -> (sqrt2/3) sqrt(eps)/l near M*'),
         ('A16', 'Sec. 2', '(sqrt2)/3 = 0.4714'), ('A17', 'Sec. 2', 'm = 10^3 l: kappa_- l = 0.9990, 4 m kappa_+ = 0.9999995'),
         ('A18', 'Sec. 4 (end)', 'q_a = 16M^3/27l^2: degenerate horizon r = 4M/3, kappa = 0'),
         ('B1', 'Sec. 5', 'P = A kappa_+^4/960 pi^2 -> 1/(15360 pi M^2)'), ('B2', 'Sec. 5', 'Lambda = 5120 pi M^3/l for M >> l'), ('B3', 'Table evap', '5120 pi = 1.608e4'),
         ('B4', 'Sec. 5', 'Lambda = (2 sqrt2/3 alpha) eps_f^(-1/2)'), ('B5', 'Sec. 5', '2 sqrt2/(3 alpha) = 6233 at alpha = 1.5126e-4'),
         ('C1', 'Sec. 6.1', 'G_ab = 8 pi T_ab (all four components) <=> Eqs. dn1, dn2 and the constraints [exact, symbolic]'),
         ('C2', 'Sec. 6.1', 'the check can fail: omitting dn1, dn2 or a constraint leaves a residual'), ('C3', 'Sec. 6.1', 'Box phi = 0 <=> Eq. dn3'),
         ('C4', 'Sec. 6.1', 'Misner-Sharp mass: 1-2M/r = g^ab r_a r_b'), ('C5', 'Sec. 6.4', 'Kretschmann = R2^2 + 8 H_AB H^AB/r^2 + 4(2M/r)^2/r^4 [exact, generic jets]'),
         ('C6', 'Sec. 6.4', 'H_AB H^AB = (8/W^2)(H_uu H_vv + H_uv^2)'), ('C7', 'Eq. consT', 'nabla_a T^a_u, nabla_a T^a_v [exact]'),
         ('C8', 'Sec. 6.2', 'conservation => d rho ^ d r = 0'), ('C9', 'Sec. 6.2', 'p_t = -rho - r rho\'/2'),
         ('C10', 'Eq. ray', "(ln y)' = rho/r - sigma_v + S/y"), ('C11', 'Eq. ray', "rho' = sigma_v rho + 4 pi r phi_v^2"), ('C12', 'Eq. muv', 'mu_v = -8 pi r^2 (r_u/W) phi_v^2'),
         ('C13', 'Sec. 6.3', 'd_u(r_u/W) = -4 pi r phi_u^2/W <= 0'), ('C14', 'Eq. Kscalar', 'K -> 2048 pi^2 (phi_u phi_v/W)^2'), ('C15', 'Eq. Kscalar', '2048 pi^2 Y^2 = 128 pi^2 [(grad phi)^2]^2'),
         ('C16', 'Sec. 6.4', 'Weyl invariant C^2 = K/6'), ('C17', 'Sec. 6.4', 'd ln K/dv = 2 kappa_- - (2k+2)/(v+1)'), ('C18', 'Sec. 6.4', 'K >= 16 M^2/r^6 (mass term)'),
         ('C19', 'Sec. 6.6', 'W_sV = W e^{kappa v}/kappa'), ('C20', 'Eq. Tq', 'T^q_vv = -hbar(sigma_v^2 - 2 sigma_vv)/192 pi^2 r^2'), ('C21', 'Sec. 6.7', 'v_flip criterion'),
         ('C22', 'Sec. 6.1', 'm_N=5, a_N=10: r_- = 1.057475, r_+ = 9.897927, kappa_- = 0.795649, kappa_+ = 0.048969'),
         ('C23_mN3', 'Sec. 6.5', 'kappa_-(m_N = 3) = 0.653'), ('C23_mN2', 'Sec. 6.5', 'kappa_-(m_N = 2) = 0.463'), ('C23_mN1.6', 'Sec. 6.5', 'kappa_-(m_N = 1.6) = 0.302'),
         ('C23_mN1.4', 'Sec. 6.5', 'kappa_-(m_N = 1.4) = 0.164')]
    for cid, wh, q in S:
        add('SYM.' + cid, wh, 'sympy: ' + q, 'OK', (lambda c, cid=cid: _sym(c, cid)), 'eq', None, 'exact symbolic identity (sympy), log: code/symbolic_checks.log', ('symbolic',))

    def _sym(c, cid):
        t = c.text('symbolic_checks.log')
        m = re.search(r'^CHECK %s: (OK|FAIL)' % re.escape(cid), t, re.M)
        if not m:
            raise KeyError('CHECK %s not in symbolic_checks.log' % cid)
        return m.group(1)

    # ================================================================================================ Sec. 2 and Sec. 4 numerics (text_numbers.py, results.json)
    TN = lambda k: (lambda c: c.TN(k))
    add('S4.I1', 'Sec. 4 (regime I)', 'G/(3M/R) - 1 at M = 1e50, s = -1/2 (double-precision limit)', '1e-13', TN('regI.dev_G_s-0.5_M1e50'), 'le', None,
        'bound is the double-precision limit of the log-space inversion', ('text_numbers',), old='less than 10^{-14}')
    add('S4.I2', 'Sec. 4 (regime I)', 's = -1: G = (3M/R) a/(R^3+a) (relative difference)', '1e-12', TN('regI.G_ratio_s-1_rel'), 'le', None, 'agreement to rounding', ('text_numbers',))
    add('S4.I3', 'Sec. 4 (regime I)', 'm_+ needed for M = 6e5 at s = -0.01: log10(m_+)', '600', TN('regI.log10_m_plus_s-0.01'), 'abs', 1.5, 'order of magnitude of the exponent ("m_+ ~ 10^600"; computed m_+/m0 = 10^600.6, m_+ = 10^601.3)', ('text_numbers',))
    add('S4.III1', 'Sec. 4 (regime III)', 'threshold s > R^3/a(m_inf)', '0.12', TN('III.s_min_fold_at_minf'), 'digits', None, '', ('text_numbers',))
    for s_, p, old in (('0.001', '588', None), ('0.01', '58', '57'), ('0.1', '5.8', None)):
        add('S4.III2_s' + s_, 'Sec. 4 (regime III)', 'fold position m_* (analytic, a(m_*) = R^3/s), s = %s' % s_, p, TN('III.mstar_s' + s_), 'digits', None,
            'analytic fold; the integration stops earlier (event at 1e-4 of dM/dm)' if s_ == '0.001' else '', ('text_numbers',), old=('m_* = 57' if old else None))
    for s_, p in (('0.001', '0.994'), ('0.01', '0.966'), ('0.1', '0.895')):
        add('S4.III3_s' + s_, 'Sec. 4 (regime III)', 'M_max/(R^3/2l^2), s = %s' % s_, p, TN('III.Mmax_over_R32_s' + s_), 'digits', None, '', ('text_numbers',))
    add('S4.III4', 'Sec. 4 (regime III)', 'R^3/2l^2', '0.591', TN('III.R32'), 'digits', None, '', ('text_numbers',))
    add('S4.III5', 'Sec. 4 (regime III)', 'M_max for s = 1 (numerical max over m equals analytic sqrt(m0 R^3/8))', '0.859696', TN('III.Mmax_num_s1'), 'digits', None, '', ('text_numbers',))
    add('S4.III6', 'Sec. 4 (regime III)', 'M_max for s = 2 (numerical max over m)', '1.298590', TN('III.Mmax_num_s2'), 'digits', None, '', ('text_numbers',))

    X = lambda c: c.text('results_extra_runs.txt')
    add('S4.II1', 'Sec. 4 (regime II)', 'advanced time at which M_+ = R^3/2l^2 (m passes through infinity), D0 = 1e-8', '36.6', lambda c: c.rx(X(c), r'M_\+ = R\^3/2l\^2 at v = \[([\d.]+)\]'), 'digits', None, '', ('extra_runs',))
    for s_, v, M_ in (('0.001', '36.55', '0.588'), ('0.01', '36.17', '0.571'), ('0.1', '32.41', '0.529')):
        add('S4.III7_s' + s_, 'Sec. 4 (regime III)', 'run stops at v* (s = %s)' % s_, v, (lambda c, s_=s_: c.rx(X(c), r's=%s: stops at v\*=([\d.]+)' % re.escape(s_))), 'digits', None, '', ('extra_runs',))
        add('S4.III8_s' + s_, 'Sec. 4 (regime III)', 'M_+(v*) (s = %s)' % s_, M_, (lambda c, s_=s_: c.rx(X(c), r's=%s: stops at v\*=[\d.]+, M_\+=([\d.]+)' % re.escape(s_))), 'digits', None, '', ('extra_runs',))
    add('S4.III9', 'Sec. 4 (regime III)', 'R^3/2 l0^2 in the run output', '0.591', lambda c: c.rx(X(c), r'R\^3/2l0\^2=([\d.]+)'), 'digits', None, '', ('extra_runs',))

    RJ = lambda c: c.json('results.json')
    add('S3.RN1', 'Sec. 3 / Table validation / abstract', 'RN: kappa_- from the fit of the growth rate', '3.74996', lambda c: RJ(c)['RN']['fit']['kappa_fit'], 'digits', None, '', ('make_results',))
    add('S3.RN2', 'Table validation', 'RN: exact kappa_- = (r_+ - r_-)/2 r_-^2', '3.75', lambda c: RJ(c)['RN']['kappa'], 'abs', 1e-9, 'exact value', ('make_results',))
    add('S3.RN3', 'Sec. 3', 'RN fit coefficient c1', '-4.995', lambda c: RJ(c)['RN']['fit']['c1'], 'digits', None, '', ('make_results',))
    for v, p in zip((20, 30, 40, 50, 60), ('5.07', '5.05', '5.04', '5.03', '5.02')):
        add('S3.RN4_v%d' % v, 'Sec. 3 / Table validation', 'RN: (kappa_- - dlnM/dv) v at v = %d' % v, p, (lambda c, v=v: [r for r in RJ(c)['RN']['rows'] if r[0] == v][0][2]), 'digits', None, '', ('make_results',))
    HR = lambda c, key, v: [r for r in RJ(c)['Hayward'][key]['rows'] if r[0] == v][0]
    for v, p in zip((100, 200, 400, 600), ('5.22', '5.10', '5.05', '5.03')):
        add('S3.H4_v%d' % v, 'Sec. 3', 'Hayward p=4: v dlnM/dv at v = %d' % v, p, (lambda c, v=v: HR(c, 's=0,p=4', v)[2]), 'digits', None, '', ('make_results',))
    for v, p in zip((100, 600), ('4.17', '4.03')):
        add('S3.H3_v%d' % v, 'Sec. 3 / Table validation', 'Hayward p=3: v dlnM/dv at v = %d' % v, p, (lambda c, v=v: HR(c, 's=0,p=3', v)[2]), 'digits', None, '', ('make_results',))
    for v, p in zip((200, 400, 600), ('7.15', '7.07', '7.05')):
        add('S3.H6_v%d' % v, 'Sec. 3 / Table validation', 'Hayward p=6: v dlnM/dv at v = %d' % v, p, (lambda c, v=v: HR(c, 's=0,p=6', v)[2]), 'digits', None, '', ('make_results',))
    for v, p in zip((200, 400, 600), ('0.936', '0.968', '0.979')):
        add('S3.Msat_v%d' % v, 'Sec. 3 / Table validation', 'Hayward p=4: M_+/M_sat at v = %d' % v, p, (lambda c, v=v: [r for r in RJ(c)['saturation_s0'] if r[0] == v][0][3]), 'digits', None, '', ('make_results',))
    add('S3.Msat_def', 'Sec. 3', 'deficit 1 - M_+/M_sat at v = 600, times v (= 2(p+1)/kappa_-)', '12.6', lambda c: (1 - [r for r in RJ(c)['saturation_s0'] if r[0] == 600][0][3]) * 600, 'digits', 1.5,
        'the text gives the leading term 2(p+1)/(kappa_- v) = 12.57/v; the measured deficit at v = 600 is 12.6/v', ('make_results',))
    add('S3.Msat_2pc', 'Summary', 'saturation amplitude predicted to 2% at v = 600', '0.02', lambda c: 1 - [r for r in RJ(c)['saturation_s0'] if r[0] == 600][0][3], 'abs', 0.005, 'quoted to one digit', ('make_results',))
    add('S3.kappaH', 'Sec. 3', 'Hayward kappa_- (l = 1, m_inf = 5)', '0.7956', lambda c: RJ(c)['Hayward']['s=0,p=4']['kappa_minus'], 'digits', None, '', ('make_results',))
    add('S3.H1_400', 'Table validation', 'Hayward s = -1, -1/2: late growth rate at v = 400', '0.7831', lambda c: HR(c, 's=-1,p=4', 400)[1], 'digits', None, '', ('make_results',))
    add('S3.H1_def', 'Table validation', 'Hayward s = -1: deficit (kappa_- - rate) v at v = 400', '5.0', lambda c: (RJ(c)['Hayward']['s=-1,p=4']['kappa_minus'] - HR(c, 's=-1,p=4', 400)[1]) * 400, 'digits', None, '', ('make_results',))
    add('S3.H1_coinc', 'Sec. 4 (regime I) / Fig. classes', 's = -1 and s = -1/2 curves coincide: max |rate difference|', '1e-8', lambda c: max(abs(a[1] - b[1]) for a, b in zip(RJ(c)['Hayward']['s=-1,p=4']['rows'], RJ(c)['Hayward']['s=-0.5,p=4']['rows'])),
        'le', None, 'coincide to the plotted accuracy', ('make_results',))
    # fold table
    FT = lambda c, s, D0, col: [r for r in RJ(c)['fold_breakdown'][s]['rows'] if abs(r[0] / D0 - 1) < 1e-9][0][col]
    rows = [('s=1', 1e-6, '28.84', 'digits', None, ''), ('s=1', 1e-9, '39.63', 'digits', None, ''), ('s=1', 1e-12, '49.8', 'abs', 0.1, 'D0 = 1e-12 is of the order of the integrator tolerance (text: quoted to three digits, +-0.1)'),
            ('s=2', 1e-6, '29.04', 'digits', None, ''), ('s=2', 1e-9, '39.81', 'digits', None, ''), ('s=2', 1e-12, '50.0', 'abs', 0.1, 'D0 = 1e-12 is of the order of the integrator tolerance (text: +-0.1 for s = 2)')]
    for s, D0, p, kd, tl, rs in rows:
        add('S4.T_v_%s_%g' % (s, D0), 'Table fold', 'v* for %s, D0 = %g' % (s, D0), p, (lambda c, s=s, D0=D0: FT(c, s, D0, 1)), kd, tl, rs, ('make_results',))
        add('S4.T_M_%s_%g' % (s, D0), 'Table fold', 'M_+(v*) for %s, D0 = %g' % (s, D0), '0.859696' if s == 's=1' else '1.298590', (lambda c, s=s, D0=D0: FT(c, s, D0, 2)), 'digits', None, '', ('make_results',))
    add('S4.T_inc1', 'Sec. 4', 'v* increment between successive seeds (s = 1), first', '10.8', lambda c: FT(c, 's=1', 1e-9, 1) - FT(c, 's=1', 1e-6, 1), 'digits', None, '', ('make_results',))
    add('S4.T_inc2', 'Sec. 4', 'v* increment between successive seeds (s = 1), second', '10.2', lambda c: FT(c, 's=1', 1e-12, 1) - FT(c, 's=1', 1e-9, 1), 'digits', None, '', ('make_results',))
    add('S4.T_inc_pe', 'Sec. 4', 'increase per e-fold of D0 (mean of the four increments / ln 10^3)', '1.5', lambda c: sum([FT(c, s, 1e-9, 1) - FT(c, s, 1e-6, 1) + FT(c, s, 1e-12, 1) - FT(c, s, 1e-9, 1) for s in ('s=1', 's=2')]) / 4 / math.log(1e3),
        'digits', None, '', ('make_results',))
    add('S4.T_indep', 'Sec. 4', 'fold value independent of the seed: max relative spread of M_+(v*) over D0 (s = 1, 2)', '1e-6', lambda c: max((max(FT(c, s, d, 2) for d in (1e-6, 1e-9, 1e-12)) - min(FT(c, s, d, 2) for d in (1e-6, 1e-9, 1e-12))) / FT(c, s, 1e-6, 2) for s in ('s=1', 's=2')),
        'le', None, '', ('make_results',))
    add('S4.T_Mmax', 'Table fold', 'M_max analytic (s = 1) at the last R', '0.859696', lambda c: RJ(c)['fold_breakdown']['s=1']['analytic_Mmax_at_last_R'], 'digits', None, '', ('make_results',))
    # integrator scan (Reproducibility section)
    FS = lambda c: c.text('fold_integrator_scan.log')

    def lsoda_rows(c):
        out = {}
        for m in re.finditer(r'^LSODA\s+(\S+)\s+\(([\d., ]+)\)\s+\(([\d., ]+)\)', FS(c), re.M):
            out[float(m.group(1))] = ([float(x) for x in m.group(2).split(',')], [float(x) for x in m.group(3).split(',')])
        return out

    def other_rows(c):
        return [(m.group(1), float(m.group(2)), float(re.findall(r'[\d.]+', m.group(3))[0]), float(re.findall(r'[\d.]+', m.group(4))[0])) for m in re.finditer(r'^(DOP853|Radau|RK45)\s+(\S+)\s+\(([\d.]+)\)\s+\(([\d.]+)\)', FS(c), re.M)]

    add('S4.INT2', 'Reproducibility', 'LSODA rtol 1e-10 ... 3e-14, s = 1: v*(D0=1e-12) within 49.8 +- 0.1', 'True',
        lambda c: all(abs(r[0][2] - 49.8) <= 0.1 for r in lsoda_rows(c).values()) and len(lsoda_rows(c)) >= 4, 'bool', None, 'text: "49.8"; computed 49.796-49.804', ('fold_integrator_scan',),
        old='at relative tolerance 2e-14 the same system gave 49.80 for s=1 [scipy refuses rtol < 2.2e-14]')
    add('S4.INT3', 'Reproducibility', 'LSODA rtol 1e-10 ... 3e-14, s = 2: v*(D0=1e-12) within 50.0 +- 0.1', 'True',
        lambda c: all(abs(r[1][2] - 50.0) <= 0.1 for r in lsoda_rows(c).values()) and len(lsoda_rows(c)) >= 4, 'bool', None, 'text: "50.0 (+-0.1 for s = 2)"; computed 49.94-49.98', ('fold_integrator_scan',),
        old='49.89-49.96 for s=2')
    add('S4.INT4', 'Reproducibility', 'DOP853, Radau, RK45 at rtol 1e-12, 1e-13: all v* within 49.8 +- 0.1 (s = 1) and 50.0 +- 0.1 (s = 2)', 'True',
        lambda c: len(other_rows(c)) >= 6 and all(abs(r[2] - 49.8) <= 0.1 and abs(r[3] - 50.0) <= 0.1 for r in other_rows(c)), 'bool', None,
        'computed 49.77-49.87 (s = 1), 49.97-50.03 (s = 2); no integrator gives 48.5', ('fold_integrator_scan',), old='a different integrator at 1e-12 gave 48.5')

    # ================================================================================================ Sec. 5 evaporation
    ET = lambda c: c.json('evap_table.json')
    row = lambda c, Mi, eps: [r for r in ET(c) if abs(r[0] - Mi) < 1e-9 and abs(r[1] / eps - 1) < 1e-9][0]
    for Mi, eps, up, Lp, rp in ((20, 0.1, '1.31e8', '1.21e8', '1.51e4'), (20, 1e-4, '2.01e8', '1.22e8', '1.52e4'), (20, 1e-6, '6.78e9', '1.27e8', '1.59e4'), (1000, 0.1, '1.61e13', '1.61e13', '1.606e4')):
        add('S5.u_%g_%g' % (Mi, eps), 'Table evap', 'u for M_i/l = %g, eps_f = %g' % (Mi, eps), up, (lambda c, Mi=Mi, eps=eps: row(c, Mi, eps)[2]), 'digits', None, '', ('evap_table',))
        add('S5.L_%g_%g' % (Mi, eps), 'Table evap', 'Lambda for M_i/l = %g, eps_f = %g' % (Mi, eps), Lp, (lambda c, Mi=Mi, eps=eps: row(c, Mi, eps)[3]), 'digits', None, '', ('evap_table',))
        add('S5.R_%g_%g' % (Mi, eps), 'Table evap', 'Lambda/(M_i^3/l) for M_i/l = %g, eps_f = %g' % (Mi, eps), rp, (lambda c, Mi=Mi, eps=eps: row(c, Mi, eps)[4]), 'digits', None, '', ('evap_table',))
    add('S5.R_inf', 'Table evap', '5120 pi', '1.608e4', lambda c: 5120 * math.pi, 'digits', None, 'arithmetic', ())
    add('S5.Mi', 'Sec. 5', 'M_i/l for 10 M_sun, l = l_P', '9.1e38', TN('evap.Mi_over_l'), 'digits', None, '', ('text_numbers',))
    add('S5.Lam', 'Sec. 5 / abstract', 'Lambda = 5120 pi M_i^3 for 10 M_sun', '1.2e121', TN('evap.Lambda_10Msun'), 'digits', None, '', ('text_numbers',))
    EA = lambda c: c.text('evap_alpha.log')
    add('S5.alpha', 'Sec. 5', 'alpha = c0/M*', '1.513e-4', lambda c: c.rx(EA(c), r'alpha = c0/M\* = ([\d.e+-]+)'), 'digits', None, '', ('evap_alpha',))
    add('S5.6233', 'Sec. 5', '2 sqrt2/(3 alpha)', '6233', lambda c: c.rx(EA(c), r'\(3 alpha\) = ([\d.]+)'), 'digits', None, '', ('evap_alpha',))
