    # ================================================================================================ Sec. 6.4 lower bound: ln K >= 16 M^2/r^6 (e13)
    def e13rows(c, tag):
        t = c.runout('eh_e13', G3_IDX[tag]) if True else ''
        out = {}
        for l in t.split('\n'):
            m = re.match(r'^\s*(\d+)\s+(-?[\d.]+)\s+([+-][\d.e+-]+)\s+([+-][\d.e+-]+)\s+([+-][\d.e+-]+)\s+\|\s+(.*?)\s+\|\s+(\S+)\s+\|\s+(\S+)\s*$', l)
            if m:
                out[int(m.group(1))] = (float(m.group(3)), float(m.group(8)))
        return out
    G3_IDX = {'B0.03_k0.5': 0, 'B0.03_k1.5': 1, 'B0.03_k2': 2, 'B0.03_k3': 3, 'B0.003_k0.5': 4, 'B0.003_k1.5': 5, 'B0.003_k2': 6, 'B0.003_k3': 7}
    for tag, p in (('B0.03_k1.5', '337'), ('B0.03_k0.5', '360'), ('B0.003_k1.5', '323'), ('B0.003_k0.5', '343')):
        add('S6.4.LK_' + tag, 'Sec. 6.4 (lower bound)', 'ln K >= ln(16 M^2/r^6) at v = 280, ray U = 0.9993, ' + tag, p, (lambda c, tag=tag: e13rows(c, tag)[280][1]), 'digits', 1.0, '', ('eh_e13',))
        add('S6.4.LK_' + tag + '@full', 'Sec. 6.4 (lower bound)', 'ln K >= ... [regenerated], ' + tag, p, (lambda c, tag=tag: _e13_full(c, tag)), 'digits', 1.0, '', ('full_eh_e13',), True)

    def _e13_full(c, tag):
        t = c.runout('full_eh_e13', G3_IDX[tag])
        m = re.search(r'^\s*280\s+(-?[\d.]+)\s+([+-][\d.e+-]+)\s+.*\|\s+(\S+)\s*$', t, re.M)
        return float(m.group(3))
    for B_, p in (('0.03', '1.4e-6'), ('0.003', '2.3e-6')):
        add('S6.6.PD_' + B_, 'Sec. 6.6 (Mass)', 'ln M_cc - ln M_ODE at v = 280 (largest over k = 1/2, 3/2, 2, 3), B = ' + B_, p,
            (lambda c, B_=B_: max(abs(e13rows(c, 'B%s_k%s' % (B_, k))[280][0]) for k in ('0.5', '1.5', '2', '3'))), 'digits', 1.0, 'quoted to two digits (1.39e-6, 2.34e-6)', ('eh_e13',))
    add('S6.6.PD_k1.5', 'Sec. 6.6 (Mass)', 'ln M_cc - ln M_ODE at v = 280, B = 0.03, k = 3/2', '3e-7', lambda c: abs(e13rows(c, 'B0.03_k1.5')[280][0]), 'digits', 1.0, 'quoted to one digit (3.3e-7)', ('eh_e13',))

    # ================================================================================================ Table ext (e15)
    def e15blocks(c, rel='eh_init/results_e15_extend.txt'):
        t = c.text(rel)
        out = {}
        for blk in re.split(r'(?m)^(?=gen3_)', t):
            m = re.match(r'gen3_B([\d.]+)_k([\d.]+)_v300\.json', blk)
            if not m:
                continue
            d = {}
            d['L100'] = c.rx(blk, r'Lambda\(280\)-Lambda\(100\)=([+-][\d.e+-]+)')
            d['L200'] = c.rx(blk, r'Lambda\(280\)-Lambda\(200\) = ([+-][\d.e+-]+)')
            d['qe'] = c.rx(blk, r'qe=([\d.]+)')
            d['rem'] = c.rx(blk, r'int_280\^inf e dv = ([\d.e+-]+)')
            d['dJ'] = c.rx(blk, r'\(([\d.e+-]+) of J\(280\)\)')
            d['dJp'] = c.rx(blk, r'= ([\d.e+-]+) of J_phi\(280\)')
            out[(m.group(1), m.group(2))] = d
        return out
