    add('S6.5.F6', 'Sec. 6.5', 'fixed domain, m_N = 1.4: A_*', '0.0503', lambda c: c.rx(FL(c), r'm_N=1\.4 .*A\*=([\d.]+)'), 'digits', None, '', ('nl_kappa_fixedL',))
