    add('S6.6.E12@full', 'Sec. 6.6', 'PDE/kernel ratio (mean, 150 <= v <= 420) [regenerated v1 = 450 run]', '1.00030', lambda c: sum(e12row(c, v)[0] for v in (150, 200, 250, 300, 350, 400, 420)) / 7, 'digits', 1.0, 'regenerated four-grid run', ('full_eh_e12',), True)

    # ================================================================================================ Sec. 6.7 semiclassical
    SC = lambda c: c.text('eh_init/results_e8_semiclassical.txt')

    def sc_row(c, eps):
        for l in SC(c).split('\n'):
            m = re.match(r'^\s*([\d.e+-]+)\s+([\d.e+-]+)\s+(nan|[\d.]+)\s+([+-][\d.e+-]+)\s+([\d.]+)\s+([+-]1)\s+\[', l)
            if m and ((eps == 0 and float(m.group(1)) == 0) or (eps != 0 and abs(float(m.group(1)) / eps - 1) < 1e-6)):
                return dict(T=float(m.group(2)), vflip=float(m.group(3)), dr=float(m.group(4)), lnM=float(m.group(5)), sign=int(m.group(6)))
        raise KeyError(eps)
    for eps, T_, vf, dr, lm, sg in ((0.0, '0', None, '-5.3e-11', '2312.33', 1), (1e-15, '3.0e-19', '2670', '-5.3e-11', '2312.10', -1), (1e-12, '3.0e-16', '679', '-3.9e-11', '2319.82', -1),
                                    (1e-10, '3.0e-14', '280', '+1.3e-9', '2324.42', -1), (1e-8, '3.0e-12', '159', '+1.4e-7', '2329.03', -1), (1e-6, '3.0e-10', '103', '+1.4e-5', '2333.63', -1),
                                    (1e-4, '3.0e-8', '62', '+1.4e-3', '2338.24', -1)):
        tg = '%g' % eps
        if eps > 0:
            add('S6.7.T_%s' % tg, 'Table semiclassical', '|T^q_vv| for eps = %s' % tg, T_, (lambda c, eps=eps: sc_row(c, eps)['T']), 'digits', None, '', ('eh_e8_semiclassical',))
            add('S6.7.v_%s' % tg, 'Table semiclassical', 'v_flip for eps = %s' % tg, vf, (lambda c, eps=eps: sc_row(c, eps)['vflip']), 'digits', None, '', ('eh_e8_semiclassical',))
        add('S6.7.r_%s' % tg, 'Table semiclassical', 'r(3000) - r(250) for eps = %s' % tg, dr, (lambda c, eps=eps: sc_row(c, eps)['dr']), 'digits', None, '', ('eh_e8_semiclassical',))
        add('S6.7.M_%s' % tg, 'Table semiclassical', 'ln|M|(3000) for eps = %s' % tg, lm, (lambda c, eps=eps: sc_row(c, eps)['lnM']), 'digits', None, '', ('eh_e8_semiclassical',))
        add('S6.7.s_%s' % tg, 'Table semiclassical', 'sign of M(3000) for eps = %s' % tg, str(sg), (lambda c, eps=eps, sg=sg: sc_row(c, eps)['sign']), 'eq', None, '', ('eh_e8_semiclassical',))
    FR = lambda c: c.text('eh_init/results_e8_flip_ratio.txt')
    for eps, p in (('1e-10', '0.96'), ('1e-08', '0.91'), ('1e-06', '0.88'), ('1e-04', '0.44')):
        add('S6.7.FR_' + eps, 'Sec. 6.7', 'phi_v^2/|T^q_vv| at v_flip, eps = ' + eps, p, (lambda c, eps=eps: c.rx(FR(c), r'^\s*%s\s+[\d.]+\s+([\d.]+)' % re.escape(eps))), 'digits', None, '', ('eh_e8_flip_ratio',))
        add('S6.7.FR_' + eps + '@full', 'Sec. 6.7', 'phi_v^2/|T^q_vv| at v_flip, eps = %s [regenerated]' % eps, p, (lambda c, eps=eps: c.rx(FR(c), r'^\s*%s\s+[\d.]+\s+([\d.]+)' % re.escape(eps))), 'digits', None, '', ('full_eh_flip',), True)
    # ================================================================================================ additional statements of the text
    add('S2.Mstar', 'Sec. 2', 'M* = 3 sqrt3 l/4', '1.299', lambda c: 3 * math.sqrt(3) / 4, 'digits', None, 'arithmetic', ())
    an('S6.3.d1', 'Sec. 6.3', 'smallest distance A_*-A scanned', '1e-10', 'thr.d_min_h0.04', 'rel', 1e-9, 'grid of distances 10^-10 ... 10^-3')
    an('S6.3.d2', 'Sec. 6.3', 'largest distance A_*-A scanned', '1e-3', 'thr.d_max_h0.04', 'rel', 1e-9, 'grid of distances 10^-10 ... 10^-3')
    for k_, p in (('2', '0.011'), ('3', '0.009')):
        add('S6.6.E_L100_k' + k_, 'Sec. 6.6', 'Lambda(280) - Lambda(100) for B = 0.03, k = ' + k_, p, (lambda c, k_=k_: abs(e15blocks(c)[('0.03', k_)]['L100'])), 'digits', 1.2, 'quoted to two digits', ('eh_e15',))
    add('S6.6.E_Jle', 'Sec. 6.6', 'k >= 3/2: fraction of J accumulated between v = 200 and 280 (max over the six runs)', '5e-5', lambda c: max(d['dJ'] for (B_, k_), d in e15blocks(c).items() if k_ != '0.5'), 'le', None, '', ('eh_e15',))
    add('S6.6.E_Jphile', 'Sec. 6.6', 'k >= 3/2: fraction of J_phi accumulated between v = 200 and 280 (max over the six runs)', '1e-2', lambda c: max(d['dJp'] for (B_, k_), d in e15blocks(c).items() if k_ != '0.5'), 'le', None, '', ('eh_e15',))
    add('S6.6.E_L200', 'Sec. 6.6', 'k >= 3/2: |Lambda(280) - Lambda(200)| (max over the six runs, text: 8e-4)', '1e-3', lambda c: max(abs(d['L200']) for (B_, k_), d in e15blocks(c).items() if k_ != '0.5'), 'le', None, '', ('eh_e15',))
    add('S6.6.E_rem', 'Sec. 6.6', 'k >= 3/2: remainder estimate (max over the six runs, text: <= 7e-4)', '7e-4', lambda c: max(d['rem'] for (B_, k_), d in e15blocks(c).items() if k_ != '0.5'), 'le', 0.01, '', ('eh_e15',))
    add('S6.6.lnM280', 'Sec. 6.6 (Mass)', 'ln M at v = 280 on the ray U = 0.9993 (B = 0.03, k = 3/2): "M ~ e^170"', '170', lambda c: float(re.search(r'^\s*280\s+(-?[\d.]+)', c.runout('eh_e13', 1), re.M).group(1)), 'rel', 0.03, 'order of magnitude statement (167)', ('eh_e13',))
    add('S6.7.vflip1', 'Sec. 6.7 / abstract', 'v_flip for eps = 1e-15 is before v = 3000', '3000', lambda c: sc_row(c, 1e-15)['vflip'], 'le', None, '', ('eh_e8_semiclassical',))
    add('S6.7.vflip2', 'Sec. 6.7 / abstract', 'v_flip for eps = 1e-6 is inside the PDE window (v_b = 250)', '250', lambda c: sc_row(c, 1e-6)['vflip'], 'le', None, '', ('eh_e8_semiclassical',))
    add('S6.7.vflip3', 'Sec. 6.7', '|ln M| keeps growing after the flip at the rate kappa_-: ln|M|(3000) increases with eps by', '4.6', lambda c: sc_row(c, 1e-6)['lnM'] - sc_row(c, 1e-8)['lnM'], 'digits', None, 'consistent with a shift of v_flip only (no change of the exponent)', ('eh_e8_semiclassical',))
    E11 = lambda c: c.text('eh_init/results_e11_ratio.txt')
    add('S6.6.E11a', 'Sec. 6.6 (Flux)', 'B = 0.03, k = 3/2: flux above the static-hole response at v = 280 [%]', '3.5', lambda c: (c.rx(E11(c), r'^B0\.03_k1\.5\s+(?:\S+\s+){4}(\S+)') - 1) * 100, 'digits', None, '', ('eh_e11_ratio',))
    add('S6.6.E11b', 'Sec. 6.6 (Flux)', 'B = 0.03, k = 1/2: flux above the static-hole response at v = 280 [%]', '3.5', lambda c: (c.rx(E11(c), r'^B0\.03_k0\.5\s+(?:\S+\s+){4}(\S+)') - 1) * 100, 'digits', None, '', ('eh_e11_ratio',))
    add('S6.fig1', 'Fig. classes', 'fig_ori_classes.png regenerated (size > 20 kB)', '20000', lambda c: os.path.getsize(os.path.join(os.path.dirname(c.root), 'fig_ori_classes.png')), 'ge', None, '', ('make_results',))
    add('S6.fig2', 'Fig. nl', 'fig_nonlinear.png regenerated (size > 20 kB)', '20000', lambda c: os.path.getsize(os.path.join(os.path.dirname(c.root), 'fig_nonlinear.png')), 'ge', None, '', ('nl_figure',))

    return CH
